                    rows.append(row)
            continue
        if selected_kind in monitoring_transfer.ROOT_KINDS:
            for row in monitoring_transfer.catalogue(workspace, selected_kind):
                if not query or query in canonical(row).decode("utf-8").casefold():
                    rows.append(row)
            continue
        if selected_kind in community_transfer.ROOT_KINDS or selected_kind in conservation_transfer.ROOT_KINDS:
            provider = community_transfer if selected_kind in community_transfer.ROOT_KINDS else conservation_transfer
            for row in provider.catalogue(workspace, selected_kind):
                if not query or query in canonical(row).decode("utf-8").casefold():
                    rows.append(row)
            continue
        if selected_kind in receptor_transfer.ROOT_KINDS:
            for row in receptor_transfer.catalogue(workspace, selected_kind):
                if not query or query in canonical(row).decode("utf-8").casefold():
                    rows.append(row)
            continue
        if selected_kind == "robust-decisions":
            from .decision_study_transfer import catalogue
            for row in catalogue(workspace):
                if not query or query in canonical(row).decode("utf-8").casefold():
                    rows.append(row)
            continue
        spatial_review = selected_kind == "spatial-reviews"
        pattern = "*.json" if spatial_review else "*/" + DOCUMENTS[selected_kind]
        for path in (workspace.root / selected_kind).glob(pattern):
            key = path.stem if spatial_review else path.parent.name
            try:
                identifier(key)
                value = read_json(_member(workspace.root, path.relative_to(workspace.root).as_posix()))
                if spatial_review:
                    if (value.get("schema") != "upstate.spatial-reviews/v1"
                            or value.get("project_id") != workspace.project["id"]
                            or digest(value) != key):
                        raise ValueError("The saved map review differs from its original identity or project.")
                    selection, state = value, {**value, "state": "complete"}
                elif selected_kind == "spatial-exports":
                    if (value.get("schema") != "upstate.spatial-export/v1"
                            or value.get("project_id") != workspace.project["id"]
                            or value.get("id") != key):
                        raise ValueError("The saved map export differs from its original identity or project.")
